import{z as o,x as i,o as t,c,q as B,j as s,D as E,d as r,s as A,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"canary","description":"","frontmatter":{"title":"canary","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/stack-canary.md","filePath":"cs/stack-canary.md","lastUpdated":1791063341000}'),d={name:"cs/stack-canary.md"};function p(C,a,D,h,m,u){const n=i("Mermaid");return t(),c("div",null,[a[2]||(a[2]=B('<h1 id="canary" tabindex="-1">canary <a class="header-anchor" href="#canary" aria-label="Permalink to &quot;canary&quot;">​</a></h1><div class="epigraph"><p>在返回地址前放一枚秘密值，函数退出前核对。踏过缓冲往往会先改掉它，于是程序选择中止而不是跳进地狱。它检测相邻覆盖，不定义所有内存安全。</p><footer>—— Cowan et al., StackGuard；对照 GCC `-fstack-protector` 的合同</footer></div><p>上一课<a href="/cs/stack-smashing-shellcode">栈溢出</a>说明返回地址可被邻接覆盖。缺口是<strong>编译器插入的检测</strong>：canary。不是形式验证，是廉价完整性检查。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若覆盖是从低地址连续写到返回地址，中间的 canary 会被改。核对失败则 abort。缺口：跳过 canary 的写（指针写）、泄漏 canary 值、不保护的函数未插桩。本课不给绕过步骤。<span class="marginnote">术语翻译：canary（金丝雀）就是函数帧里放在缓冲区与返回地址之间的一枚随机哨兵值——矿工带金丝雀下井，它先出事就先报警；这里的哨兵先被踩坏，退出前核对不上就中止进程。</span></p><h3 id="终止策略" tabindex="-1">终止策略 <a class="header-anchor" href="#终止策略" aria-label="Permalink to &quot;终止策略&quot;">​</a></h3><p>发现后应中止进程。试图「修复栈再继续」会把完整性游戏做坏。</p><p><span class="marginnote">StackGuard。SSP 把 canary 当每线程秘密。Fork 后要重种的讨论点名即可。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照无保护帧与插桩帧。指出优化可能不给叶子函数插 canary。强调与 NX 正交：一个管执行许可，一个管邻接覆盖检测。<span class="marginnote">直觉类比：NX 与 canary 是两把不同的锁——NX 锁「这块内存能不能执行」，canary 管「返回地址有没有被顺路改坏」；只装一把，另一条路照样开着。</span></p>',11)),(t(),s(l,null,{default:E(()=>[A(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20ENT%5B%22%E5%87%BD%E6%95%B0%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20CAN%5B%22%E5%86%99%E5%85%A5%20canary%22%5D%0A%20%20CAN%20--%3E%20BODY%5B%22%E5%87%BD%E6%95%B0%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20CHK%5B%22%E9%80%80%E5%87%BA%E5%89%8D%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20CHK%20--%3E%20AB%5B%22%E5%A4%B1%E8%B4%A5%E5%88%99%E4%B8%AD%E6%AD%A2%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[r("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[r("缓解是概率与覆盖形状上的：连续溢出被抓住，任意写不一定。下一课 ROP：在不可执行栈上仍可能拼已有代码碎片——只讲存在性与防御方向，不给 gadget 序列。"),e("span",{class:"marginnote"},"常见误区：以为开了栈保护就等于内存安全。canary 的合同只覆盖「从缓冲区连续写过去」这一种形状——指针任意写可以一步跳到返回地址，根本不经过哨兵。")],-1)),(t(),s(l,null,{default:E(()=>[A(n,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20WR%5B%22%E4%B8%80%E6%AC%A1%E8%B6%8A%E7%95%8C%E5%86%99%22%5D%20--%3E%20KIND%7B%22%E5%86%99%E7%9A%84%E5%BD%A2%E7%8A%B6%E6%98%AF%E5%93%AA%E7%A7%8D%EF%BC%9F%22%7D%0A%20%20KIND%20--%3E%7C%22%E7%BC%93%E5%86%B2%E5%8C%BA%E8%BF%9E%E7%BB%AD%E6%BA%A2%E5%87%BA%22%7C%20PASS%5B%22%E5%BF%85%E7%84%B6%E8%B8%8F%E8%BF%87%20canary%22%5D%0A%20%20PASS%20--%3E%20HIT%5B%22%E9%80%80%E5%87%BA%E5%89%8D%E6%A0%B8%E5%AF%B9%22%5D%0A%20%20HIT%20--%3E%7C%22%E5%80%BC%E5%8F%98%E4%BA%86%22%7C%20ABORT%5B%22%E4%B8%AD%E6%AD%A2%E8%BF%9B%E7%A8%8B%22%5D%0A%20%20KIND%20--%3E%7C%22%E6%8C%87%E9%92%88%E4%BB%BB%E6%84%8F%E5%86%99%22%7C%20SKIP%5B%22%E4%B8%80%E6%AD%A5%E6%94%B9%E8%BF%94%E5%9B%9E%E5%9C%B0%E5%9D%80%EF%BC%8C%E4%B8%8D%E7%BB%8F%E8%BF%87%E5%93%A8%E5%85%B5%22%5D%0A%20%20KIND%20--%3E%7C%22%E5%85%88%E8%AF%BB%E5%90%8E%E5%86%99%22%7C%20LEAK%5B%22%E5%80%BC%E8%A2%AB%E8%AF%BB%E8%B5%B0%EF%BC%8C%E5%86%99%E5%9B%9E%E5%8E%9F%E5%80%BC%E5%8D%B3%E5%8F%AF%22%5D%0A%20%20SKIP%20--%3E%20GAP%5B%22%E5%90%88%E5%90%8C%E4%B9%8B%E5%A4%96%EF%BC%9A%E4%BA%A4%20ASLR%20%E4%B8%8E%E5%AE%89%E5%85%A8%E7%BC%96%E7%A0%81%22%5D%0A%20%20LEAK%20--%3E%20GAP%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写泄漏 canary 的方法。ROP 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>邻接覆盖返回地址时，中间秘密可被踏到。</li><li>核对失败则中止；不是内存安全。</li><li>任意写与泄漏不在 canary 合同内。</li><li>下一课 ROP（机制，无 gadget 教程）。</li><li>出处：Cowan et al., StackGuard；GCC 栈保护文档。</li></ul>',4))])}const F=o(d,[["render",p]]);export{f as __pageData,F as default};
